examples.template:
VStack(spacing: theme.spacing.space4) {
    MonarchButton({{askLabel}}, variant: .secondary, size: .md, fullWidth: true) {}
    VStack {
        MonarchAiOnboardingTour(
            [
                MonarchAiOnboardingTourStep({{steps.0.title}}, body: {{steps.0.body}}),
                MonarchAiOnboardingTourStep({{steps.1.title}}, body: {{steps.1.body}}),
                MonarchAiOnboardingTourStep({{steps.2.title}}, body: {{steps.2.body}}),
            ],
            onSkip: {},
            onDisable: {},
            onFinish: {}
        )
    }
    .padding(theme.spacing.space4)
    .background(
        RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous)
            .strokeBorder(theme.colors.aiBorder, lineWidth: 1)
    )
}
.padding(.horizontal)

